import{_ as a,o as t,c as n,a3 as o}from"./chunks/framework.Cc-oPviL.js";const g=JSON.parse('{"title":"04 · IO 模型与零拷贝：等设备的时候，CPU 在干什么","description":"","frontmatter":{},"headers":[],"relativePath":"bagu/os/04.md","filePath":"bagu/os/04.md"}'),e={name:"bagu/os/04.md"};function l(p,s,i,r,c,d){return t(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="_04-·-io-模型与零拷贝-等设备的时候-cpu-在干什么" tabindex="-1">04 · IO 模型与零拷贝：等设备的时候，CPU 在干什么 <a class="header-anchor" href="#_04-·-io-模型与零拷贝-等设备的时候-cpu-在干什么" aria-label="Permalink to &quot;04 · IO 模型与零拷贝：等设备的时候，CPU 在干什么&quot;">​</a></h1><blockquote><p>这篇是 OS 模块里最&quot;工程&quot;的一篇，也是面试问得最深的一篇。 它同时串起了 01（阻塞态）、03（调度）、02（mmap）。</p></blockquote><h2 id="一句话本质" tabindex="-1">一句话本质 <a class="header-anchor" href="#一句话本质" aria-label="Permalink to &quot;一句话本质&quot;">​</a></h2><p>IO 的本质是**&quot;等&quot;<strong>：等磁盘转、等网卡收包。所谓&quot;五种 IO 模型&quot;，区别只在于</strong>这段时间谁来等、CPU 能不能干别的**。</p><h2 id="生活类比-点外卖" tabindex="-1">生活类比：点外卖 <a class="header-anchor" href="#生活类比-点外卖" aria-label="Permalink to &quot;生活类比：点外卖&quot;">​</a></h2><table tabindex="0"><thead><tr><th>IO 模型</th><th>外卖场景</th></tr></thead><tbody><tr><td><strong>阻塞 IO</strong></td><td>你站在门口一直等，什么都不干，直到骑手到</td></tr><tr><td><strong>非阻塞 IO</strong></td><td>你每 30 秒下楼看一次，没到就回去干点活（但来回跑很累）</td></tr><tr><td><strong>IO 多路复用</strong></td><td>你装了个门铃，同时等 5 个外卖，谁到了门铃响，你只处理到了的那个</td></tr><tr><td><strong>信号驱动 IO</strong></td><td>你告诉骑手&quot;到了给我打电话&quot;，然后安心干活，电话来了再去拿</td></tr><tr><td><strong>异步 IO</strong></td><td>你雇了个跑腿，他拿到外卖<strong>送到你手上</strong>才叫你</td></tr></tbody></table><p><strong>关键差别在最后一格</strong>：前四种都是&quot;<strong>数据到了，你自己去搬</strong>&quot;，只有异步 IO 是&quot;<strong>数据搬完了才通知你</strong>&quot;。</p><h2 id="核心机制" tabindex="-1">核心机制 <a class="header-anchor" href="#核心机制" aria-label="Permalink to &quot;核心机制&quot;">​</a></h2><h3 id="一、一次网络读操作的两个阶段-这是理解一切的基础" tabindex="-1">一、一次网络读操作的两个阶段（这是理解一切的基础） <a class="header-anchor" href="#一、一次网络读操作的两个阶段-这是理解一切的基础" aria-label="Permalink to &quot;一、一次网络读操作的两个阶段（这是理解一切的基础）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段一：等数据到达</span></span>
<span class="line"><span>  网卡收到包 &gt; 内核把数据从网卡拷到内核缓冲区（socket 接收缓冲区）</span></span>
<span class="line"><span>  这期间：数据还没到用户能拿的地方</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段二：把数据从内核缓冲区拷到用户缓冲区</span></span>
<span class="line"><span>  内核 &gt; 用户，一次内存拷贝（这一步一定要 CPU 参与）</span></span></code></pre></div><p><strong>五种 IO 模型的差别，全部落在这两个阶段上</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                阶段一（等数据）        阶段二（拷贝数据）</span></span>
<span class="line"><span>阻塞 IO          阻塞                  阻塞</span></span>
<span class="line"><span>非阻塞 IO        轮询（不阻塞）          阻塞</span></span>
<span class="line"><span>IO 多路复用       阻塞在 select/epoll    阻塞</span></span>
<span class="line"><span>信号驱动 IO       不阻塞（信号通知）      阻塞</span></span>
<span class="line"><span>异步 IO          不阻塞                 不阻塞  &lt; 只有这个第二阶段也不阻塞</span></span></code></pre></div><p><strong>一句话记住</strong>：前四种是&quot;同步 IO&quot;（因为第二阶段都要你自己等拷贝完成），只有 AIO 是真正的异步。</p><h3 id="二、io-多路复用-select-poll-epoll" tabindex="-1">二、IO 多路复用：select / poll / epoll <a class="header-anchor" href="#二、io-多路复用-select-poll-epoll" aria-label="Permalink to &quot;二、IO 多路复用：select / poll / epoll&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>select（1983）</span></span>
<span class="line"><span>  每次调用：把整个 fd 集合从用户态拷到内核态 &gt; 内核遍历所有 fd 检查 &gt; 返回后用户再遍历一遍找谁就绪</span></span>
<span class="line"><span>  问题：① fd 上限 1024（FD_SETSIZE）② 每次都要全量拷贝 ③ O(n) 遍历</span></span>
<span class="line"><span></span></span>
<span class="line"><span>poll（1997）</span></span>
<span class="line"><span>  用链表代替位图，解决了 1024 上限</span></span>
<span class="line"><span>  问题：全量拷贝和 O(n) 遍历还在</span></span>
<span class="line"><span></span></span>
<span class="line"><span>epoll（2002，Linux 2.6）</span></span>
<span class="line"><span>  三个关键改动：</span></span>
<span class="line"><span>  ① epoll_create 建一个内核事件表，fd 只需注册一次（不用每次拷）</span></span>
<span class="line"><span>  ② 内核用回调机制：fd 就绪时主动把事件挂到就绪链表（不用遍历）</span></span>
<span class="line"><span>  ③ epoll_wait 只返回就绪的那几个（O(1) 级别，与总 fd 数无关）</span></span></code></pre></div><p><strong>epoll 快的真正原因（必答三点）</strong>：</p><ol><li><strong>不用每次全量拷贝</strong> fd 集合（注册一次，长期有效）。</li><li><strong>不用遍历所有 fd</strong>（内核回调把就绪的挂到链表，直接取）。</li><li><strong>只返回就绪的 fd</strong>（用户态也不用遍历）。</li></ol><p>注意：<strong>epoll 不是&quot;永远更快&quot;</strong>。fd 少且都活跃时（比如 10 个连接全都一直在收发），select 的遍历开销很小，epoll 的回调注册反而有额外成本。epoll 的优势在<strong>fd 多但活跃的少</strong>（典型 Web 服务器：1 万连接，同时活跃几十个）。</p><h3 id="三、水平触发-lt-vs-边缘触发-et" tabindex="-1">三、水平触发（LT）vs 边缘触发（ET） <a class="header-anchor" href="#三、水平触发-lt-vs-边缘触发-et" aria-label="Permalink to &quot;三、水平触发（LT）vs 边缘触发（ET）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>水平触发（LT，默认）：</span></span>
<span class="line"><span>  只要缓冲区还有数据，epoll_wait 就一直返回这个 fd</span></span>
<span class="line"><span>  &gt; 编程简单：可以一次只读一点，下次还会通知</span></span>
<span class="line"><span>  &gt; 但如果忘了读，会一直空转通知（忙循环）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>边缘触发（ET）：</span></span>
<span class="line"><span>  只在&quot;状态变化&quot;时通知一次（从没数据 &gt; 有数据）</span></span>
<span class="line"><span>  &gt; 必须一次读到 EAGAIN 为止，否则剩下的数据没人通知你</span></span>
<span class="line"><span>  &gt; 效率更高（通知次数少），但编程容易出错</span></span></code></pre></div><p><strong>ET 模式的铁律</strong>：<strong>必须配合非阻塞 fd + 循环读到 <code>EAGAIN</code></strong>。否则会漏数据。</p><h3 id="四、reactor-与-proactor" tabindex="-1">四、Reactor 与 Proactor <a class="header-anchor" href="#四、reactor-与-proactor" aria-label="Permalink to &quot;四、Reactor 与 Proactor&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Reactor（对应 IO 多路复用）</span></span>
<span class="line"><span>  主线程：epoll_wait 等事件 &gt; 分发给 handler &gt; handler 自己 read/write</span></span>
<span class="line"><span>  特点：事件通知的是&quot;可以读了&quot;，读的动作还是你自己做</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Proactor（对应异步 IO）</span></span>
<span class="line"><span>  主线程：发起 aio_read &gt; 内核读完数据 &gt; 通知&quot;读完了，数据在这&quot;</span></span>
<span class="line"><span>  特点：事件通知的是&quot;读完了&quot;，你直接处理数据</span></span></code></pre></div><p>Linux 上的 AIO 一直不成熟（<code>io_uring</code> 是 2019 年才真正好用），所以主流网络框架（Nginx、Redis、Netty）<strong>都是 Reactor</strong>。Windows 的 IOCP 是真正的 Proactor。</p><h3 id="五、零拷贝-为什么要-零" tabindex="-1">五、零拷贝：为什么要&quot;零&quot; <a class="header-anchor" href="#五、零拷贝-为什么要-零" aria-label="Permalink to &quot;五、零拷贝：为什么要&quot;零&quot;&quot;">​</a></h3><p>普通读文件 + 发网络，数据要拷 4 次、切换 4 次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 &gt; 内核页缓存    （DMA 拷贝，不占 CPU）</span></span>
<span class="line"><span>内核页缓存 &gt; 用户缓冲区  （CPU 拷贝 ①）</span></span>
<span class="line"><span>用户缓冲区 &gt; socket 缓冲区 （CPU 拷贝 ②）</span></span>
<span class="line"><span>socket 缓冲区 &gt; 网卡   （DMA 拷贝）</span></span>
<span class="line"><span>+ 4 次用户态/内核态切换</span></span></code></pre></div><p><strong>sendfile</strong>：数据不经过用户态，直接从页缓存到 socket 缓冲区。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 &gt; 页缓存（DMA） &gt; socket 缓冲区（CPU 拷贝） &gt; 网卡（DMA）</span></span>
<span class="line"><span>+ 2 次切换，1 次 CPU 拷贝</span></span></code></pre></div><p><strong>sendfile + DMA gather</strong>（真正的零拷贝）：连那 1 次 CPU 拷贝也省了，只传&quot;页的描述符&quot;给网卡，由网卡自己按描述符去内存取。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>磁盘 &gt; 页缓存（DMA） &gt; 网卡（DMA，直接按描述符取）</span></span>
<span class="line"><span>+ 2 次切换，0 次 CPU 拷贝</span></span></code></pre></div><p><strong>mmap + write</strong>：把文件映射进用户地址空间，省掉&quot;读&quot;的那次拷贝，但&quot;写&quot;的那次还在。适合需要<strong>读写文件内容</strong>的场景（Kafka 用这个）。</p><h2 id="为什么这么设计" tabindex="-1">为什么这么设计 <a class="header-anchor" href="#为什么这么设计" aria-label="Permalink to &quot;为什么这么设计&quot;">​</a></h2><h3 id="反事实-1-如果没有-io-多路复用-会怎样" tabindex="-1">反事实 1：如果没有 IO 多路复用，会怎样 <a class="header-anchor" href="#反事实-1-如果没有-io-多路复用-会怎样" aria-label="Permalink to &quot;反事实 1：如果没有 IO 多路复用，会怎样&quot;">​</a></h3><p>一个服务器要处理 1 万个连接。用&quot;一连接一线程&quot;：</p><ul><li>1 万线程 × 1MB 栈 = 10GB 内存</li><li>每个线程大部分时间在阻塞等数据，但内核要维护 1 万个线程的调度</li></ul><p>用&quot;一连接一进程&quot;更惨。这就是 C10K 问题的由来——<strong>问题不是 CPU 不够，是&quot;等待&quot;的方式太贵</strong>。</p><h3 id="反事实-2-如果没有零拷贝-会怎样" tabindex="-1">反事实 2：如果没有零拷贝，会怎样 <a class="header-anchor" href="#反事实-2-如果没有零拷贝-会怎样" aria-label="Permalink to &quot;反事实 2：如果没有零拷贝，会怎样&quot;">​</a></h3><p>一个静态文件服务器，发 1GB 文件：</p><ul><li>4 次拷贝里，2 次是 CPU 参与的</li><li>每次拷贝都要占用内存带宽和 CPU 周期</li><li>高并发时，CPU 全耗在&quot;搬数据&quot;上，而不是&quot;处理请求&quot;上</li></ul><p>零拷贝把 CPU 从搬运工变成调度员，同样的硬件能扛几倍的吞吐。</p><h3 id="反事实-3-如果-select-没有-1024-限制-还需要-epoll-吗" tabindex="-1">反事实 3：如果 select 没有 1024 限制，还需要 epoll 吗 <a class="header-anchor" href="#反事实-3-如果-select-没有-1024-限制-还需要-epoll-吗" aria-label="Permalink to &quot;反事实 3：如果 select 没有 1024 限制，还需要 epoll 吗&quot;">​</a></h3><p>需要。1024 只是表面问题，<strong>真正的瓶颈是 O(n) 遍历</strong>。哪怕放宽到 10 万，每次 <code>select</code> 遍历 10 万个 fd 也要几十毫秒——而此时可能只有 3 个 fd 有数据。</p><h2 id="面试怎么问" tabindex="-1">面试怎么问 <a class="header-anchor" href="#面试怎么问" aria-label="Permalink to &quot;面试怎么问&quot;">​</a></h2><p><strong>Q：五种 IO 模型的区别？</strong></p><blockquote><p>用&quot;两个阶段&quot;回答，不要罗列名字。核心是：<strong>前四种的第二阶段（内核&gt;用户拷贝）都是阻塞的，所以都是同步 IO；只有 AIO 第二阶段也不阻塞</strong>。</p></blockquote><p><strong>Q：epoll 为什么比 select 快？</strong></p><blockquote><p>三点：不用全量拷贝（注册一次）、不用遍历（回调挂就绪链表）、只返回就绪 fd。 <strong>加分句</strong>：fd 少且全活跃时 epoll 不一定快，它的优势在&quot;连接多、活跃少&quot;。</p></blockquote><p><strong>Q：LT 和 ET 怎么选？</strong></p><blockquote><p>LT 编程简单、不容易漏事件，适合大多数场景（Nginx 默认用 ET 是因为它自己封装好了）。 ET 通知次数少、效率高，但<strong>必须配合非阻塞 + 循环读到 EAGAIN</strong>，否则丢数据。</p></blockquote><p><strong>Q：什么是零拷贝？</strong></p><blockquote><p>不是&quot;不拷贝&quot;，是&quot;<strong>减少 CPU 参与的拷贝次数</strong>&quot;。普通方式 4 次拷贝 4 次切换，<code>sendfile</code> 降到 1 次 CPU 拷贝，<code>sendfile + DMA gather</code> 降到 0 次。</p></blockquote><p><strong>Q：为什么 Redis 单线程还这么快？</strong></p><blockquote><p>四个原因，别只说&quot;内存&quot;： ① <strong>纯内存操作</strong>，没有磁盘 IO 的等待。 ② <strong>IO 多路复用</strong>（epoll），一个线程管上万连接，没有线程切换和锁竞争。 ③ <strong>单线程避免了锁</strong>，所有操作天然串行，不需要同步。 ④ <strong>高效的数据结构</strong>（SDS、跳表、压缩列表），常数小。 <strong>补一句</strong>：Redis 6.0 之后网络 IO 改成多线程了，但命令执行仍是单线程——因为瓶颈从来不在 CPU。</p></blockquote><p><strong>追问链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一次 read 发生了什么？</span></span>
<span class="line"><span>  &gt; 为什么数据要先到内核缓冲区？（用户态不能直接访问硬件/网卡）</span></span>
<span class="line"><span>    &gt; 那为什么还要再拷一次到用户态？（隔离，用户不能直接读内核内存）</span></span>
<span class="line"><span>      &gt; 能不能不拷？（mmap / 零拷贝）</span></span>
<span class="line"><span>        &gt; 一万个连接怎么等？（IO 多路复用）</span></span>
<span class="line"><span>          &gt; select 有什么问题？（1024 + O(n)）</span></span>
<span class="line"><span>            &gt; epoll 怎么解决的？（回调 + 就绪链表）</span></span>
<span class="line"><span>              &gt; LT 和 ET 的区别？（通知时机）</span></span></code></pre></div><h2 id="和其他知识的连接" tabindex="-1">和其他知识的连接 <a class="header-anchor" href="#和其他知识的连接" aria-label="Permalink to &quot;和其他知识的连接&quot;">​</a></h2><ul><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/01">进程与线程：谁在跑，跑的时候带着什么</a>：阻塞 IO 让进程进入阻塞态，状态机里的那条边</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/03">调度与并发同步：CPU 分给谁，共享数据谁先动</a>：IO 多路复用本质是&quot;一个线程等多个事件&quot;，替代了多线程阻塞</li><li><strong>&lt; 来自</strong> <a href="/study-hub/bagu/os/02">虚拟内存：让每个程序都以为自己独占一台机器</a>：<code>mmap</code> 是虚拟内存的应用，零拷贝建立在页缓存之上</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/network/01">分层模型与一次请求的一生</a>：内核协议栈收包后放进 socket 缓冲区，应用才读得到</li><li><strong>&gt; 影响</strong> <a href="/study-hub/bagu/db/02">事务与 ACID</a>：<code>fsync</code> 强制刷盘，本质是&quot;绕过页缓存的延迟&quot;</li><li><strong>&gt; 影响</strong> 工程实践：Nginx / Redis / Netty / Kafka 的高性能都建立在这篇之上</li></ul><h2 id="自测-3-问" tabindex="-1">自测 3 问 <a class="header-anchor" href="#自测-3-问" aria-label="Permalink to &quot;自测 3 问&quot;">​</a></h2><p><strong>Q1：为什么说前四种 IO 都是&quot;同步 IO&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为它们的<strong>第二阶段（把数据从内核缓冲区拷到用户缓冲区）都是阻塞的</strong>，都要等这个拷贝完成才能继续。</p><p>&quot;同步/异步&quot;的分界不在&quot;等数据到达时能不能干别的&quot;，而在**&quot;数据搬运这件事是谁完成的、完成时通不通知你&quot;**：</p><ul><li>同步：你自己调 <code>read</code>，调用的那一刻数据才被搬到你手上，<code>read</code> 返回时搬运已完成。</li><li>异步：你发起 <code>aio_read</code> 就返回了，内核搬完之后<strong>回调通知你</strong>，数据已经在你指定的缓冲区里了。</li></ul><p>所以非阻塞 IO 虽然第一阶段不阻塞，但第二阶段还是你自己等，仍属同步。</p></details><p><strong>Q2：ET 模式为什么必须&quot;循环读到 EAGAIN&quot;？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>因为 ET 只在<strong>状态变化</strong>时通知一次。</p><p>假设缓冲区来了 10KB 数据，你只读了 4KB 就返回了。此时状态没有变化（缓冲区一直&quot;有数据&quot;），内核<strong>不会再通知你</strong>。剩下的 6KB 就一直躺在那里，直到有新数据到达才可能再次触发——但可能永远不来，连接就&quot;假死&quot;了。</p><p>所以必须循环读到 <code>read</code> 返回 <code>EAGAIN</code>（表示&quot;现在没数据了&quot;），确保缓冲区被读空。而且必须用非阻塞 fd，否则最后那次 <code>read</code> 会把你阻塞住。</p></details><p><strong>Q3：零拷贝真的&quot;零&quot;吗？</strong></p><details class="details custom-block"><summary>点开看答案</summary><p>不是零次拷贝，是<strong>零次 CPU 参与的拷贝</strong>。</p><p>数据仍然要从磁盘到内存（DMA 拷贝，不占 CPU）、从内存到网卡（DMA 拷贝，不占 CPU）。省掉的是&quot;内核缓冲区 &gt; 用户缓冲区 &gt; socket 缓冲区&quot;这两次 <strong>CPU memcpy</strong>。</p><p>所以更准确的说法是&quot;<strong>零 CPU 拷贝</strong>&quot;或&quot;<strong>零用户态拷贝</strong>&quot;。它的收益在于：省掉 CPU 周期和内存带宽，同时把 4 次上下文切换降到 2 次。</p></details><h2 id="类比失效处-易错点" tabindex="-1">类比失效处 / 易错点 <a class="header-anchor" href="#类比失效处-易错点" aria-label="Permalink to &quot;类比失效处 / 易错点&quot;">​</a></h2><ul><li><strong>&quot;门铃&quot;类比会让人以为多路复用是&quot;并行&quot;</strong>。实际上 epoll 仍是<strong>单线程串行处理</strong>就绪的 fd，只是&quot;等待&quot;这件事被合并了。真正的并行要靠多线程/多进程（Nginx 的 worker）。</li><li><strong>epoll 不是&quot;永远更快&quot;</strong>。连接少且全活跃时，select 可能更省。</li><li><strong>&quot;零拷贝&quot;不能用于需要修改数据的场景</strong>。<code>sendfile</code> 数据不经过用户态，你就没法加工它。Kafka 用 <code>sendfile</code> 是因为它只做&quot;转发&quot;，不做处理；要加密/压缩就得用 <code>mmap</code> 或退回普通方式。</li><li><strong>AIO 在 Linux 上长期不成熟</strong>。<code>io_uring</code> 之前，Linux 的 POSIX AIO 是用线程模拟的，不是真异步。所以&quot;Linux 支持 AIO&quot;这句话要加限定。</li><li><strong><code>epoll_wait</code> 的 O(1) 是&quot;返回就绪 fd&quot;的开销</strong>，不是&quot;处理事件&quot;的开销。事件处理本身还是 O(就绪数)。</li></ul><h2 id="✅-验收清单" tabindex="-1">✅ 验收清单 <a class="header-anchor" href="#✅-验收清单" aria-label="Permalink to &quot;✅ 验收清单&quot;">​</a></h2><ul><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="0"> 能画出&quot;两个阶段&quot;的图，并把五种 IO 模型填进表格（哪个阶段阻塞/不阻塞）</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="1"> 能说出&quot;为什么前四种是同步 IO、只有 AIO 是异步&quot;的判据</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="2"> 能说出 epoll 比 select 快的<strong>三个</strong>原因，并能补一句&quot;什么时候 epoll 不占优&quot;</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="3"> 能解释 LT 和 ET 的区别，以及 ET 为什么必须循环读到 EAGAIN</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="4"> 能画出普通 IO 的 4 次拷贝 4 次切换，并说出 sendfile 省掉了哪几次</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="5"> 能用四个原因解释&quot;Redis 单线程为什么快&quot;，并说出 6.0 的改动</li><li class="sh-task-item"><input type="checkbox" class="sh-task" data-i="6"> 合上书，用自己的话讲 3 分钟，中途不卡壳</li></ul>`,69)])])}const h=a(e,[["render",l]]);export{g as __pageData,h as default};
